/* app.client.2.js — Client Portal: samples, worklist, results, work queue, printing */
'use strict';
/* ---------- samples ---------- */
function sampleTransition(s, status, location) { s.status = status; s.events.push({ status, time: nowISO(), user: userName(), location: location || (status === 'Collected' ? 'Phlebotomy' : L(grp(s.group))) }); }
App.screens.collection = () => { const mode = App.store.scanMode || 'Collected'; const all = DB.visits.flatMap(v => v.samples.map(s => ({ ...s, v }))); const todayS = all.filter(x => isToday(x.v.date)); const cnt = st => todayS.filter(x => x.status === st).length;
  return pageHead(t('collectionReceipt'), `${t('samples')} / ${t('collectionReceipt')}`) + `<div class="grid2"><div>${card({ title: t('scanSample'), sub: t('scanSub'), body: `<div class="row mb"><label class="check"><input type="radio" name="sm" ${mode === 'Collected' ? 'checked' : ''} onchange="App.store.scanMode='Collected';renderMain()"> ${t('collectMode')}</label><label class="check"><input type="radio" name="sm" ${mode === 'Received' ? 'checked' : ''} onchange="App.store.scanMode='Received';renderMain()"> ${t('receiveMode')}</label></div><div class="scan"><input class="inp" id="scanId" placeholder="S2610080001" onkeydown="if(event.key==='Enter'){scanSample(this.value);this.value=''}"><button class="btn primary" onclick="scanSample(el('#scanId').value);el('#scanId').value=''">${ic('scan')} ${t('scan')}</button></div><div class="help">${t('scanHelp')}</div><div id="scanResult" class="mt"></div>` })}${card({ title: t('byAccession'), body: `<div class="scan"><input class="inp" id="scanAcc" placeholder="2610080001" onkeydown="if(event.key==='Enter')scanAcc(this.value)"><button class="btn" onclick="scanAcc(el('#scanAcc').value)">${ic('check')} ${mode === 'Collected' ? t('collectAll') : t('receiveAll')}</button></div><div class="help">${t('byAccessionHelp')}</div>` })}</div>
${card({ title: t('todaySamples'), sub: `${t('st_Ordered')}: ${cnt('Ordered')} · ${t('st_Collected')}: ${cnt('Collected')} · ${t('st_Received')}: ${cnt('Received')} · ${t('st_Rejected')}: ${cnt('Rejected')}`, flush: true, body: grid({ cols: [{ k: 'id', l: 'sampleId', f: r => `<span class="mono">${r.id}</span>` }, { k: 'acc', l: 'accession', f: r => `<b>${r.v.acc}</b>` }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r.v))) }, { k: 'group', l: 'clinicalGroup', f: r => esc(L(grp(r.group))) }, { k: 'type', l: 'sample', f: r => `${esc(L(stById(r.sampleType)))} · ${esc(r.condition)}` }, { k: 'services', l: 'services', f: r => r.services.map(s => svcById(s).short).join(', ') }, { k: 'status', l: 'status', f: r => sb(r.status) }, { k: 'last', l: 'lastEvent', f: r => { const e = r.events[r.events.length - 1]; return e ? `${fmtDT(e.time).slice(11)} · ${esc(e.location)}` : '—'; } }], rows: todayS.map((x, i) => ({ ...x, id: x.id })), actions: r => (r.status === 'Ordered' ? `<button class="btn sm" onclick="scanSample('${r.id}')">${t('st_Collected')}</button>` : r.status === 'Collected' ? `<button class="btn sm primary" onclick="App.store.scanMode='Received';scanSample('${r.id}')">${t('st_Received')}</button>` : '') + rowBtn('clock', 'track', `trackModal('${r.id}')`) }) })}</div>`; };
function scanSample(id) { id = String(id || '').trim().toUpperCase(); const s = sampleById(id); const out = el('#scanResult'); if (!s) { toast(t('sampleNotFound'), 'error', id); return; } const v = visitOfSample(id); const mode = App.store.scanMode || 'Collected';
  if (s.status === 'Rejected') { toast(t('sampleRejectedScan'), 'error', s.rejectReason); return; }
  if (mode === 'Collected') { if (s.status !== 'Ordered') toast(t('alreadyStatus'), 'warn', t('st_' + s.status)); else { sampleTransition(s, 'Collected', 'Phlebotomy'); audit('Sample collected', id, ''); toast(t('markedCollected'), 'ok', id); } }
  else { if (s.status === 'Ordered') { sampleTransition(s, 'Collected', 'Phlebotomy'); } if (s.status === 'Received') toast(t('alreadyStatus'), 'warn', t('st_Received')); else { sampleTransition(s, 'Received', L(grp(s.group))); audit('Sample received', id, L(grp(s.group))); toast(t('markedReceived'), 'ok', id); } }
  if (out) out.innerHTML = `<div class="module-card"><div><b>${id}</b> · ${esc(L(patientOf(v)))} · ${v.acc}<p>${esc(L(grp(s.group)))} · ${esc(L(stById(s.sampleType)))} · ${esc(s.condition)} · ${s.services.map(x => svcById(x).short).join(', ')}</p></div>${sb(s.status)}</div>`; renderMain(); setTimeout(() => { const i = el('#scanId'); if (i) i.focus(); const o = el('#scanResult'); if (o && out) o.innerHTML = out.innerHTML; }, 0); }
function scanAcc(acc) { const v = visitByAcc(acc); if (!v) return toast(t('visitNotFound'), 'error'); const mode = App.store.scanMode || 'Collected'; v.samples.forEach(s => { if (s.status === 'Rejected') return; if (mode === 'Collected' && s.status === 'Ordered') sampleTransition(s, 'Collected', 'Phlebotomy'); if (mode === 'Received' && s.status !== 'Received') { if (s.status === 'Ordered') sampleTransition(s, 'Collected', 'Phlebotomy'); sampleTransition(s, 'Received', L(grp(s.group))); } }); renderMain(); toast(mode === 'Collected' ? t('markedCollected') : t('markedReceived'), 'ok', `${v.acc} · ${v.samples.length}`); }
App.screens.samplesByVisit = p => { const acc = p.acc || App.store.sbvAcc || ''; App.store.sbvAcc = acc; const v = acc ? visitByAcc(acc) : null; return pageHead(t('samplesByVisit'), `${t('samples')} / ${t('samplesByVisit')}`) + card({ body: `<div class="scan"><input class="inp" id="sbv" value="${esc(acc)}" placeholder="${t('accession')}" onkeydown="if(event.key==='Enter')navigate('samplesByVisit',{acc:this.value})"><button class="btn primary" onclick="navigate('samplesByVisit',{acc:el('#sbv').value})">${ic('search')} ${t('search')}</button></div>` }) + (v ? card({ title: `${v.acc} · ${esc(L(patientOf(v)))}`, actions: `<button class="btn sm" onclick="docLabels(${v.id})">${ic('printer', 14)} ${t('printLabels')}</button><button class="btn sm" onclick="docJobOrder(${v.id})">${ic('file', 14)} ${t('jobOrder')}</button>`, flush: true, body: grid({ cols: [{ k: 'id', l: 'sampleId', f: r => `<span class="mono">${r.id}</span>` }, { k: 'group', l: 'unit', f: r => `[${grp(r.group).unitCode}] ${esc(L(grp(r.group)))}` }, { k: 'type', l: 'sample', f: r => `${esc(L(stById(r.sampleType)))} · ${esc(r.condition)}` }, { k: 'status', l: 'status', f: r => sb(r.status) + (r.rejectReason ? ` <span class="small muted">${esc(r.rejectReason)}</span>` : '') }, { k: 'date', l: 'statusDate', f: r => fmtDT(r.events[r.events.length - 1]?.time) }, { k: 'labels', l: 'labels', f: r => r.labels + '×' }, { k: 'services', l: 'services', f: r => r.services.map(s => { const sv = svcById(s); return `<span class="tag">${sv.short} <span class="muted">(${t('svt_' + sv.type)})</span></span>`; }).join('') }], rows: v.samples, nofoot: true, actions: r => rowBtn('printer', 'printLabel', `modal({title:'${t('sampleLabels')}',size:'sm',body:labelHtml(byId(DB.visits,${v.id}),sampleById('${r.id}')),foot:'<button class=\\'btn primary\\' onclick=\\'closeModal();toast(t(\\"sentToPrinter\\"),\\"ok\\")\\'>${t('print')}</button>'})`) + rowBtn('clock', 'track', `trackModal('${r.id}')`) }) }) : (acc ? `<div class="bad-strip">${t('visitNotFound')}</div>` : '')); };
App.screens.rejectSample = () => pageHead(t('rejectUnreject'), `${t('samples')} / ${t('rejectUnreject')}`) + `<div class="grid2">${card({ title: t('rejectSample'), sub: t('rejectSub'), body: `<div class="scan mb"><input class="inp" id="rjId" placeholder="S2610080006" onkeydown="if(event.key==='Enter')rjLookup(this.value)"><button class="btn" onclick="rjLookup(el('#rjId').value)">${ic('search')} ${t('lookup')}</button></div><div id="rjInfo"></div>` })}${card({ title: t('unrejectReplace'), sub: t('unrejectSub'), body: `<div class="scan mb"><input class="inp" id="urId" placeholder="S…" onkeydown="if(event.key==='Enter')urLookup(this.value)"><button class="btn" onclick="urLookup(el('#urId').value)">${ic('search')} ${t('lookup')}</button></div><div id="urInfo"></div><div class="info mt">${DB.parameters.newBarcodeOnReject ? t('policyNewBarcode') : t('policySameBarcode')}</div>` })}</div>` + card({ title: t('rejectedSamples'), flush: true, body: grid({ cols: [{ k: 'id', l: 'sampleId', f: r => `<span class="mono">${r.id}</span>` }, { k: 'acc', l: 'accession', f: r => r.v.acc }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r.v))) }, { k: 'reason', l: 'reason', f: r => badge(r.rejectReason, 'bad') }, { k: 'when', l: 'date', f: r => fmtDT(r.events[r.events.length - 1]?.time) }, { k: 'by', l: 'user', f: r => esc(r.events[r.events.length - 1]?.user) }], rows: DB.visits.flatMap(v => v.samples.filter(s => s.status === 'Rejected').map(s => ({ ...s, v }))), nofoot: true }) });
function rjLookup(id) { id = id.trim().toUpperCase(); const s = sampleById(id); const box = el('#rjInfo'); if (!s) return box.innerHTML = `<div class="bad-strip">${t('sampleNotFound')}</div>`; const v = visitOfSample(id); if (s.status === 'Rejected') return box.innerHTML = `<div class="warn-strip">${t('alreadyRejected')} · ${esc(s.rejectReason)}</div>`; box.innerHTML = `<div class="kv mb"><dt>${t('accession')}</dt><dd>${v.acc}</dd><dt>${t('patient')}</dt><dd>${esc(L(patientOf(v)))}</dd><dt>${t('sample')}</dt><dd>${esc(L(stById(s.sampleType)))} · ${esc(s.condition)} · ${s.services.map(x => svcById(x).short).join(', ')}</dd><dt>${t('status')}</dt><dd>${sb(s.status)}</dd></div><div class="field"><label>${t('rejectionReason')} <span class="req">*</span></label><select class="inp" id="rjReason"><option value="">${t('select')}</option>${reasonOpts('Rejection').map(([v2, l]) => `<option value="${v2}">${esc(l())}</option>`).join('')}</select></div><button class="btn danger mt" onclick="rjConfirm('${id}')">${ic('slash')} ${t('rejectSample')}</button>`; }
function rjConfirm(id) { const reason = el('#rjReason').value; if (!reason) return toast(t('selectReason'), 'error'); confirmDlg(t('rejectSample'), t('rejectConfirm') + ` <b>${id}</b>?`, () => { const s = sampleById(id); s.status = 'Rejected'; s.rejectReason = reason; s.events.push({ status: 'Rejected', time: nowISO(), user: userName(), location: L(grp(s.group)) + ' · ' + reason }); audit('Sample rejected', id, reason); renderMain(); toast(t('sampleRejected'), 'warn', `${id} · ${reason} · ${t('notifyRecollect')}`); }, true); }
function urLookup(id) { id = id.trim().toUpperCase(); const s = sampleById(id); const box = el('#urInfo'); if (!s) return box.innerHTML = `<div class="bad-strip">${t('sampleNotFound')}</div>`; if (s.status !== 'Rejected') return box.innerHTML = `<div class="warn-strip">${t('notRejected')} · ${sb(s.status)}</div>`; box.innerHTML = `<div class="kv mb"><dt>${t('sample')}</dt><dd>${id} · ${esc(s.rejectReason)}</dd></div><div class="row"><button class="btn" onclick="unreject('${id}')">${ic('undo')} ${t('unrejectSameBarcode')}</button><button class="btn primary" onclick="replaceSample('${id}')">${ic('plus')} ${t('issueNewSample')}</button></div>`; }
function unreject(id) { const s = sampleById(id); s.status = 'Received'; s.events.push({ status: 'Received', time: nowISO(), user: userName(), location: L(grp(s.group)) + ' · unreject' }); audit('Sample unrejected', id, ''); renderMain(); toast(t('sampleReinstated'), 'ok', id); }
function replaceSample(id) { const old = sampleById(id); const v = visitOfSample(id); const ns = { id: `S${v.acc}${pad(v.samples.length + 1, 2)}`, group: old.group, sampleType: old.sampleType, condition: old.condition, status: 'Ordered', events: [{ status: 'Ordered', time: nowISO(), user: userName(), location: 'Replacement of ' + id }], labels: old.labels, rejectReason: '', services: [...old.services] }; old.services = []; v.samples.push(ns); audit('Replacement sample', ns.id, 'replaces ' + id); renderMain(); modal({ title: t('newSampleIssued'), size: 'sm', body: `<div class="ok-strip">${ns.id} ${t('replaces')} ${id}</div>${labelHtml(v, ns)}`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button><button class="btn primary" onclick="closeModal();toast(t('sentToPrinter'),'ok')">${ic('printer')} ${t('printLabel')}</button>` }); }
App.screens.sampleTracking = p => pageHead(t('sampleTracking'), `${t('samples')} / ${t('sampleTracking')}`) + card({ body: `<div class="scan"><input class="inp" id="trk" placeholder="S2610080001" onkeydown="if(event.key==='Enter')trackModal(this.value)"><button class="btn primary" onclick="trackModal(el('#trk').value)">${ic('clock')} ${t('track')}</button></div><div class="help">${t('trackHelp')}</div>` }) + card({ title: t('recentSamples'), flush: true, body: grid({ cols: [{ k: 'id', l: 'sampleId', f: r => `<span class="mono">${r.id}</span>` }, { k: 'acc', l: 'accession', f: r => r.v.acc }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r.v))) }, { k: 'group', l: 'unit', f: r => esc(L(grp(r.group))) }, { k: 'status', l: 'status', f: r => sb(r.status) }, { k: 'stages', l: 'stages', f: r => r.events.map(e => `<span class="tag">${e.status} ${fmtDT(e.time).slice(11)}</span>`).join('') }], rows: DB.visits.flatMap(v => v.samples.map(s => ({ ...s, v }))).slice(0, 12), nofoot: true, actions: r => rowBtn('clock', 'track', `trackModal('${r.id}')`) }) });
function trackModal(id) { id = String(id).trim().toUpperCase(); const s = sampleById(id); if (!s) return toast(t('sampleNotFound'), 'error', id); const v = visitOfSample(id); const rs = DB.results.filter(r => r.visit === v.id && s.services.includes(r.service)); const stage = st => rs.flatMap(r => r.statusLog.filter(x => x.status === st)).sort((a, b) => a.time.localeCompare(b.time))[0]?.time; const durs = s.events.map((e, i) => i ? { from: s.events[i - 1].status, to: e.status, h: hoursBetween(s.events[i - 1].time, e.time) } : null).filter(Boolean);
  modal({ title: `${t('sampleTracking')} · ${id}`, size: 'lg', body: `<div class="kv mb"><dt>${t('accession')}</dt><dd>${v.acc} · ${esc(L(patientOf(v)))}</dd><dt>${t('unit')}</dt><dd>${esc(L(grp(s.group)))} · ${esc(L(stById(s.sampleType)))} · ${esc(s.condition)}</dd><dt>${t('services')}</dt><dd>${s.services.map(x => svcById(x).short).join(', ')}</dd><dt>${t('status')}</dt><dd>${sb(s.status)}</dd></div><div class="grid3"><div><div class="section-title">${t('locationsStatuses')}</div><ul class="timeline">${s.events.map(e => `<li><time>${fmtDT(e.time)}</time><div>${sb(e.status)}<div class="small muted">${esc(e.location)} · ${esc(e.user)}</div></div></li>`).join('')}</ul></div><div><div class="section-title">${t('timeBetweenStages')}</div><ul class="timeline">${durs.map(d => `<li><time>${fmtDur(d.h)}</time><div>${d.from} → ${d.to}</div></li>`).join('') || `<li class="muted">—</li>`}</ul></div><div><div class="section-title">${t('testRoundTime')}</div><dl class="kv">${['Complete', 'Reviewed', 'Verified', 'Printed'].map(st => `<dt>${t('st_' + st)}</dt><dd>${stage(st) ? fmtDT(stage(st)) : '—'}</dd>`).join('')}</dl></div></div>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button>` }); }

/* ---------- worklist ---------- */
function worklistRows(f) {
  const rows = []; DB.results.forEach(r => { const v = byId(DB.visits, r.visit); if (!v) return; const tst = testById(r.test); const s = svcById(r.service); const line = v.lines.find(l => l.service === s.id || (svcById(l.service)?.type === 'Package' && svcById(l.service).members.some(m => m.service === s.id))); if (!line || line.status !== 'Ordered') return; const smp = v.samples.find(x => x.services.includes(s.id)); const colEv = smp?.events.find(e => e.status === 'Collected'); const collected = colEv ? colEv.time : null; const base = collected || v.date; const expected = expectedResultDate(base, tst.durationH); const delay = hoursBetween(expected, NOW()); const pctC = Math.min(130, Math.round(hoursBetween(base, NOW()) / (tst.durationH || 24) * 100)); const mapped = DB.analyzerTests.some(m => m.test === r.test && byId(DB.analyzers, m.analyzer)?.status === 'Active'); rows.push({ id: r.id, r, v, tst, s, acc: v.acc, patient: L(patientOf(v)), test: L(tst), group: tst.group, sample: smp, sampleStatus: smp?.status || '—', status: r.status, collected, expected, delay, pctC, manual: !mapped, printed: r.printed, analyzers: DB.analyzerTests.filter(m => m.test === r.test).map(m => m.analyzer) }); });
  return rows.filter(x => { if (f.from && (!x.collected || x.collected < f.from)) return false; if (f.to && x.collected && x.collected.slice(0, 10) > f.to) return false; if (f.group && String(x.group) !== String(f.group)) return false; if (f.test && String(x.tst.id) !== String(f.test)) return false; if (f.analyzer && !x.analyzers.includes(Number(f.analyzer))) return false; if (f.sampleStatus && x.sampleStatus !== f.sampleStatus) return false; if (f.payer && String(x.v.payer) !== String(f.payer)) return false; const b = f.boxes || {}; const any = Object.values(b).some(Boolean); if (!any) return true; return (b.newTests && x.status === 'Ordered') || (b.remaining && stIdx(x.status) < 3) || (b.completed && x.status === 'Complete') || (b.manual && x.manual) || (b.notVerified && stIdx(x.status) < 3) || (b.notPrinted && !x.printed) || (b.incomplete && x.status === 'Ordered') || (b.printed && x.printed) || (b.delayed && x.delay > 0 && stIdx(x.status) < 3); });
}
function delayColor(x) { const th = String(DB.parameters.delayThresholds || '70 / 85 / 100').split('/').map(n => Number(n.trim())); if (stIdx(x.status) >= 3) return ''; if (x.pctC >= th[2]) return 'background:#F6D5DA'; if (x.pctC >= th[1]) return 'background:#FFE0CC'; if (x.pctC >= th[0]) return 'background:#FFF3B0'; return ''; }
App.screens.worklist = () => { const f = App.store.wl || (App.store.wl = { from: '', to: '', group: '', test: '', analyzer: '', sampleStatus: '', payer: '', boxes: {} }); const rows = worklistRows(f); const reqs = new Set(rows.map(x => x.v.id)).size, samples = new Set(rows.map(x => x.sample?.id).filter(Boolean)).size;
  const box = (k, l) => `<label class="check"><input type="checkbox" ${f.boxes[k] ? 'checked' : ''} onchange="App.store.wl.boxes.${k}=this.checked;renderMain()"> ${t(l)}</label>`;
  return pageHead(t('worklist'), `${t('laboratory')} / ${t('worklist')}`, `<button class="btn" onclick="App.store.wl={from:'',to:'',group:'',test:'',analyzer:'',sampleStatus:'',payer:'',boxes:{}};renderMain()">${t('clear')}</button><button class="btn primary" onclick="docWorklist()">${ic('printer')} ${t('printWorklist')}</button>`) + `<div class="info">${t('worklistNote')}</div>` +
    card({ body: `<div class="form-grid four">${field({ k: 'from', l: 'collectionFrom', type: 'date', val: f.from, onchange: "App.store.wl.from=this.value;renderMain()" })}${field({ k: 'to', l: 'collectionTo', type: 'date', val: f.to, onchange: "App.store.wl.to=this.value;renderMain()" })}${field({ k: 'group', l: 'clinicalGroup', type: 'select', opts: grpOpts(), val: f.group, onchange: "App.store.wl.group=this.value;renderMain()" })}${field({ k: 'test', l: 'test', type: 'select', opts: testOpts(), val: f.test, onchange: "App.store.wl.test=this.value;renderMain()" })}${field({ k: 'analyzer', l: 'analyzer', type: 'select', opts: opt(DB.analyzers), val: f.analyzer, onchange: "App.store.wl.analyzer=this.value;renderMain()" })}${field({ k: 'sampleStatus', l: 'sampleStatus', type: 'select', opts: ['Ordered', 'Collected', 'Received', 'Rejected'].map(x => [x, () => t('st_' + x)]), val: f.sampleStatus, onchange: "App.store.wl.sampleStatus=this.value;renderMain()" })}${field({ k: 'payer', l: 'payer', type: 'select', opts: payerOpts(), val: f.payer, onchange: "App.store.wl.payer=this.value;renderMain()" })}</div><div class="row mt" style="gap:14px">${box('newTests', 'newTests')}${box('remaining', 'remaining')}${box('completed', 'completedBox')}${box('manual', 'manualTests')}${box('notVerified', 'notVerified')}${box('notPrinted', 'notPrinted')}${box('incomplete', 'incomplete')}${box('printed', 'printedBox')}${box('delayed', 'delayed')}</div>` }) +
    card({ title: `${t('requests')}: ${reqs} · ${t('tests')}: ${rows.length} · ${t('samples')}: ${samples}`, sub: `<span class="legend"><span><i class="sw" style="background:#FFF3B0"></i>≥70 %</span><span><i class="sw" style="background:#FFE0CC"></i>≥85 %</span><span><i class="sw" style="background:#F6D5DA"></i>≥100 % ${t('ofDuration')}</span></span>`, flush: true, body: `<div class="table-wrap"><table class="g compact"><thead><tr><th>${t('patientNo')}</th><th>${t('accession')}</th><th>${t('sampleId')}</th><th>${t('patient')}</th><th>${t('ageSex')}</th><th>${t('test')}</th><th>${t('testStatus')}</th><th>${t('sampleStatus')}</th><th>${t('collected')}</th><th>${t('expectedResult')}</th><th>${t('delay')}</th><th>${t('consumed')}</th><th></th></tr></thead><tbody>${rows.map(x => `<tr style="${delayColor(x)}"><td>${patientOf(x.v).no}</td><td><b>${x.acc}</b></td><td class="mono small">${x.sample?.id || '—'}</td><td>${esc(x.patient)}</td><td class="small">${ageText(patientOf(x.v).dob)} · ${t(patientOf(x.v).sex.toLowerCase())}</td><td>${esc(x.test)}${x.manual ? ` <span class="tag">${t('manual')}</span>` : ''}</td><td>${sb(x.status)}</td><td>${x.sample ? sb(x.sampleStatus) : '—'}</td><td class="small">${fmtDT(x.collected)}</td><td class="small">${fmtDT(x.expected)}</td><td>${x.delay > 0 && stIdx(x.status) < 3 ? badge(fmtDur(x.delay), 'bad') : '—'}</td><td style="min-width:80px">${pct(x.pctC)}<span class="small muted">${x.pctC}%</span></td><td class="actions">${x.sample ? rowBtn('clock', 'track', `trackModal('${x.sample.id}')`) : ''}${rowBtn('flask', 'results', `navigate('resultsByAccession',{acc:'${x.acc}'})`)}</td></tr>`).join('') || `<tr><td colspan="13"><div class="empty">${t('noResults')}</div></td></tr>`}</tbody></table></div>` }); };
