const Res = { q: { acc: '', patientNo: '', name: '', testStatus: '', sampleStatus: '', analyzer: '', notPrinted: false, notVerified: false, delta: false }, visitId: null, sampleId: null };
function resQueryRows() { const q = Res.q; return DB.visits.filter(v => { const p = patientOf(v); if (q.acc && !v.acc.includes(q.acc.trim())) return false; if (q.patientNo && !p.no.toLowerCase().includes(q.patientNo.toLowerCase())) return false; if (q.name) { const n = q.name.toLowerCase().replace(/%/g, ''); if (!p.name.toLowerCase().includes(n) && !(p.nameAr || '').includes(n)) return false; } const rs = DB.results.filter(r => r.visit === v.id); if (q.testStatus && !rs.some(r => r.status === q.testStatus)) return false; if (q.sampleStatus && !v.samples.some(s => s.status === q.sampleStatus)) return false; if (q.analyzer && !rs.some(r => r.analyzer === q.analyzer)) return false; if (q.notPrinted && !rs.some(r => !r.printed)) return false; if (q.notVerified && !rs.some(r => stIdx(r.status) < 3)) return false; if (q.delta && !rs.some(r => r.delta)) return false; return true; }).sort((a, b) => b.date.localeCompare(a.date)); }
