  return head + `<div class="card"><div class="card-body" style="padding:6px 14px 14px">${tabs('unitTabs', items, active)}${units.map(u => pane('unitTabs', u.key, unitCard(v, u, sample), u.key === active)).join('')}</div></div>`;
