function unitActionForce(key, status) { const { v, u } = unitByKey(key); const eligible = u.results.filter(r => r.value !== '' && stIdx(r.status) < stIdx(status)); eligible.forEach(r => { r.status = status; r.statusLog.push({ status, time: nowISO(), user: userName() }); }); audit(status, v.acc, `${L(grp(u.group))} · ${eligible.length}`); renderMain(); toast(`${t('st_' + status)} · ${eligible.length}`, 'ok', status === 'Verified' ? t('eSignature') : ''); }
