function cultureModal(id) { const r = byId(DB.results, id); const c = r.culture || { noGrowth: false, organisms: [{ org: '', abx: [] }], comment: '' }; App.cult = JSON.parse(JSON.stringify(c)); const render = () => { el('#cultBody').innerHTML = `<label class="check mb"><input type="checkbox" ${App.cult.noGrowth ? 'checked' : ''} onchange="App.cult.noGrowth=this.checked;window.__cr()"> ${t('noGrowth')}</label>${App.cult.noGrowth ? '' : App.cult.organisms.map((o, i) => `<div class="card mb"><div class="card-head"><div class="row"><b>${t('organism')} ${i + 1}</b><select class="inp sm" onchange="App.cult.organisms[${i}].org=Number(this.value)"><option value="">${t('select')}</option>${DB.organisms.filter(x => x.code !== 'NOGROW').map(x => `<option value="${x.id}" ${o.org === x.id ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select></div><button class="row-btn danger" onclick="App.cult.organisms.splice(${i},1);window.__cr()">${ic('trash', 14)}</button></div><div class="card-body"><table class="g compact"><thead><tr><th>${t('antibiotic')}</th><th>${t('sensitivity')}</th><th></th></tr></thead><tbody>${o.abx.map((a, j) => `<tr><td><select class="inp sm" onchange="App.cult.organisms[${i}].abx[${j}].ab=Number(this.value)">${DB.antibiotics.map(x => `<option value="${x.id}" ${a.ab === x.id ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select></td><td><select class="inp sm" onchange="App.cult.organisms[${i}].abx[${j}].sens=this.value">${DB.sensitivities.map(s => `<option value="${s.code}" ${a.sens === s.code ? 'selected' : ''}>${s.code} · ${esc(L(s))}</option>`).join('')}</select></td><td class="actions"><button class="row-btn danger" onclick="App.cult.organisms[${i}].abx.splice(${j},1);window.__cr()">${ic('trash', 14)}</button></td></tr>`).join('')}</tbody></table><button class="btn sm mt" onclick="App.cult.organisms[${i}].abx.push({ab:DB.antibiotics[0].id,sens:'S'});window.__cr()">${ic('plus', 12)} ${t('antibiotic')}</button></div></div>`).join('') + `<button class="btn sm" onclick="App.cult.organisms.push({org:'',abx:[]});window.__cr()">${ic('plus', 12)} ${t('organism')}</button>`}<div class="field mt"><label>${t('cultureComment')}</label><textarea class="inp" rows="2" onchange="App.cult.comment=this.value">${esc(App.cult.comment)}</textarea></div>`; }; window.__cr = render; modal({ title: `${t('cultureEntry')} · ${esc(L(testById(r.test)))}`, size: 'lg', body: `<div id="cultBody"></div>`, foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn primary" onclick="saveCulture(${id})">${ic('save')} ${t('save')}</button>`, onOpen: render }); }
function saveCulture(id) { const r = byId(DB.results, id); const v = byId(DB.visits, r.visit); const smp = v.samples.find(s => s.services.includes(r.service)); if (!smp || smp.status !== 'Received') return toast(t('receivedGate'), 'error'); if (!App.cult.noGrowth && !App.cult.organisms.some(o => o.org)) return toast(t('selectOrganism'), 'error'); r.culture = App.cult; r.value = App.cult.noGrowth ? 'No growth' : 'Growth — see table'; r.flag = App.cult.noGrowth ? 'N' : 'A'; r.log.push({ value: r.value, time: nowISO(), user: userName(), analyzer: false }); if (r.status === 'Ordered') { r.status = 'Complete'; r.statusLog.push({ status: 'Complete', time: nowISO(), user: userName() }); } closeModal(); renderMain(); toast(t('saved'), 'ok'); }
