/* ---------- work queue & print list ---------- */
const WQ = { f: { from: '2026-10-01', to: today(), group: '', payer: '', analyzerFrom: '', analyzerTo: '', received: true, normal: '', boxes: {}, keep: false, sort: 'acc' }, rows: [], printList: [], printListNo: 704, selected: new Set() };
function wqRows() { const f = WQ.f; const b = f.boxes; const anyBox = Object.values(b).some(Boolean); return reportUnitsAll().filter(u => { const v = u.visit; if (f.from && v.date.slice(0, 10) < f.from) return false; if (f.to && v.date.slice(0, 10) > f.to) return false; if (f.group && String(u.group) !== f.group) return false; if (f.payer && String(v.payer) !== f.payer) return false; if (f.received && !u.received) return false; if (f.normal === 'Normal' && u.abnormal) return false; if (f.normal === 'Abnormal' && !u.abnormal) return false; if (f.analyzerFrom && !u.analyzers.includes(f.analyzerFrom)) return false; if (f.analyzerTo) { const a = DB.analyzers.find(x => x.code === f.analyzerTo); const mapped = DB.analyzerTests.filter(m => m.analyzer === a?.id).map(m => m.test); if (!u.results.some(r => mapped.includes(r.test))) return false; } if (f.manual && !u.manual) return false; if (!anyBox) return true; const s = u.status, i = stIdx(s); return (b.complete && s === 'Complete') || (b.reviewed && s === 'Reviewed') || (b.verified && s === 'Verified') || (b.printed && u.printed) || (b.notComplete && i < 1) || (b.notReviewed && i < 2) || (b.notVerified && i < 3) || (b.notPrinted && !u.printed) || (b.allVerified && u.results.every(r => stIdx(r.status) >= 3)) || (b.reserved && u.reserved) || (b.delta && u.delta); }).sort((a, b2) => f.sort === 'name' ? L(patientOf(a.visit)).localeCompare(L(patientOf(b2.visit))) : f.sort === 'date' ? a.visit.date.localeCompare(b2.visit.date) : a.visit.acc.localeCompare(b2.visit.acc)); }
App.screens.workQueue = p => { if (p.preset) { WQ.f.boxes = {}; if (p.preset === 'fromAnalyzer') { WQ.f.boxes.complete = true; WQ.f.analyzerFrom = p.analyzer; WQ.f.analyzerTo = ''; } if (p.preset === 'toAnalyzer') { WQ.f.boxes.notComplete = true; WQ.f.analyzerTo = p.analyzer; WQ.f.analyzerFrom = ''; WQ.f.received = false; } if (p.preset === 'printable') { WQ.f.boxes.verified = true; WQ.f.boxes.notPrinted = true; } } const f = WQ.f; const fresh = wqRows(); const rows = f.keep ? [...new Map([...WQ.rows, ...fresh].map(u => [u.key, u])).values()] : fresh; WQ.rows = rows;
  const box = (k, l, tip) => `<label class="check" title="${esc(tip || '')}"><input type="checkbox" ${f.boxes[k] ? 'checked' : ''} onchange="WQ.f.boxes.${k}=this.checked;renderMain()"> ${t(l)}</label>`;
  return pageHead(t('workQueue'), `${t('laboratory')} / ${t('workQueue')}`, `<button class="btn" onclick="WQ.f.boxes={};WQ.f.analyzerFrom='';WQ.f.analyzerTo='';WQ.f.keep=false;WQ.rows=[];renderMain()">${t('newSearch')}</button><button class="btn blue" onclick="navigate('workQueue',{preset:'fromAnalyzer',analyzer:'XN550'})">${ic('cpu', 14)} ${t('fromAnalyzerAwaiting')} XN550</button><button class="btn blue" onclick="navigate('workQueue',{preset:'toAnalyzer',analyzer:'XN550'})">${ic('cpu', 14)} ${t('toAnalyzerPending')} XN550</button>`) + `<div class="info">${t('wqNote')}</div>` +
    card({ body: `<div class="form-grid four">${field({ k: 'from', l: 'registrationFrom', type: 'date', val: f.from, onchange: 'WQ.f.from=this.value;renderMain()' })}${field({ k: 'to', l: 'registrationTo', type: 'date', val: f.to, onchange: 'WQ.f.to=this.value;renderMain()' })}${field({ k: 'group', l: 'clinicalGroup', type: 'select', opts: grpOpts(), val: f.group, onchange: 'WQ.f.group=this.value;renderMain()' })}${field({ k: 'payer', l: 'payer', type: 'select', opts: payerOpts(), val: f.payer, onchange: 'WQ.f.payer=this.value;renderMain()' })}${field({ k: 'af', l: 'fromAnalyzer', type: 'select', opts: DB.analyzers.map(a => [a.code, a.name]), val: f.analyzerFrom, onchange: 'WQ.f.analyzerFrom=this.value;renderMain()', help: 'fromAnalyzerHelp' })}${field({ k: 'at', l: 'toAnalyzer', type: 'select', opts: DB.analyzers.map(a => [a.code, a.name]), val: f.analyzerTo, onchange: 'WQ.f.analyzerTo=this.value;renderMain()', help: 'toAnalyzerHelp' })}${field({ k: 'normal', l: 'normalAbnormal', type: 'select', opts: [['Normal', () => t('normalOnly')], ['Abnormal', () => t('abnormalOnly')]], val: f.normal, onchange: 'WQ.f.normal=this.value;renderMain()' })}${field({ k: 'sort', l: 'sortBy', type: 'select', opts: [['acc', () => t('accession')], ['name', () => t('patientName')], ['date', () => t('registrationDate')]], val: f.sort, onchange: 'WQ.f.sort=this.value;renderMain()' })}</div>
<div class="row mt" style="gap:14px">${box('complete', 'st_Complete')}${box('reviewed', 'st_Reviewed')}${box('verified', 'st_Verified')}${box('printed', 'st_Printed')}<span class="muted">|</span>${box('notComplete', 'notComplete', t('notXHelp'))}${box('notReviewed', 'notReviewed', t('notXHelp'))}${box('notVerified', 'notVerified', t('notXHelp'))}${box('notPrinted', 'notPrinted')}${box('allVerified', 'allVerified')}${box('reserved', 'st_Reserved')}${box('delta', 'deltaCheck')}<span class="muted">|</span><label class="check"><input type="checkbox" ${f.received ? 'checked' : ''} onchange="WQ.f.received=this.checked;renderMain()"> ${t('receivedOnly')}</label><label class="check"><input type="checkbox" ${f.manual ? 'checked' : ''} onchange="WQ.f.manual=this.checked;renderMain()"> ${t('manualTests')}</label><label class="check"><input type="checkbox" ${f.keep ? 'checked' : ''} onchange="WQ.f.keep=this.checked"> ${t('keepPrevious')}</label></div><div class="help">${t('notXHelp')} · ${t('receivedToggleHelp')}</div>` }) +
    `<div class="split" style="grid-template-columns:minmax(0,1fr) 320px"><div class="card"><div class="card-head"><div><div class="card-title">${t('count')}: ${rows.length}</div><div class="card-sub legend">${[['#FFD6E0', 'uc_incNP'], ['#1D3F8F', 'uc_incP'], ['#F28B82', 'uc_compNP'], ['#8E6CD6', 'uc_compP'], ['#C9F0D5', 'uc_revNP'], ['#F6B5C5', 'uc_revP'], ['#2B2B2B', 'uc_verNP'], ['#5FC48F', 'uc_verP'], ['#FFF3B0', 'uc_reservedNP']].map(([c, k]) => `<span><i class="sw" style="background:${c}"></i>${t(k)}</span>`).join('')}</div></div><div class="row"><button class="btn sm blue" onclick="wqBulk('Reviewed')">${ic('check', 14)} ${t('reviewAll')}</button><button class="btn sm ok" onclick="wqBulk('Verified')">${ic('checkcircle', 14)} ${t('verifyAll')}</button><button class="btn sm" onclick="WQ.rows.forEach(u=>wqAddPrint(u.key,true));renderMain()">${ic('plus', 14)} ${t('addAllToPrintList')}</button></div></div><div class="table-wrap"><table class="g compact"><thead><tr><th></th><th>${t('accession')}</th><th>${t('patient')}</th><th>${t('clinicalGroup')}</th><th>${t('services')}</th><th>${t('sampleIds')}</th><th>${t('status')}</th><th>${t('printed')}</th><th></th></tr></thead><tbody>${rows.map(u => { const c = unitColor(u); return `<tr ondblclick="wqAddPrint('${u.key}')" style="cursor:pointer" title="${t('dblclickAdd')}"><td><span class="st-color" style="background:${c[0]}"></span></td><td><b>${u.visit.acc}</b></td><td>${esc(L(patientOf(u.visit)))}</td><td>${esc(L(grp(u.group)))}</td><td>${u.services.map(x => `<span class="tag">${x.service.short}</span>`).join('')}</td><td class="mono small">${u.samples.map(s => s.id).join(', ')}</td><td>${sb(u.status)}${u.abnormal ? ' ' + badge(t('abnormal'), 'bad') : ''}${u.delta ? ' ' + badge('Δ', 'warn') : ''}</td><td>${u.printed ? ic('check', 14) : ''}</td><td class="actions"><button class="btn sm" onclick="Res.q.acc='${u.visit.acc}';navigate('resultsByAccession',{acc:'${u.visit.acc}'})">R</button></td></tr>`; }).join('') || `<tr><td colspan="9"><div class="empty">${t('noResults')} — ${t('emptyQueueHint')}</div></td></tr>`}</tbody></table></div><div class="grid-foot"><span>${rows.length ? `${t('selectedRow')}: ${unitColor(rows[0])[1]} & ${t('sample')}: ${rows[0].received ? t('st_Received') : t('notReceived')}` : ''}</span></div></div>
<div class="card sidecard"><div class="card-head"><div class="card-title">${t('printList')} ${WQ.printListNo > 704 ? '#' + WQ.printListNo : ''}</div><button class="link" onclick="WQ.printList=[];renderMain()">${t('clearAll')}</button></div><div class="card-body"><div class="row mb"><input class="inp sm" id="plAcc" placeholder="${t('addAccession')}" onkeydown="if(event.key==='Enter'){wqAddAcc(this.value);this.value=''}"><button class="btn sm" onclick="wqAddAcc(el('#plAcc').value)">${ic('plus', 12)}</button></div><ul class="timeline">${WQ.printList.map(k => { const { u } = unitByKey(k); return `<li><time>${u.visit.acc}</time><div>${esc(L(patientOf(u.visit)))} · ${esc(L(grp(u.group)))} ${stIdx(u.status) < 3 ? badge(t('notVerifiedShort'), 'bad') : ''}<button class="link" style="margin-inline-start:6px" onclick="WQ.printList=WQ.printList.filter(x=>x!=='${k}');renderMain()">×</button></div></li>`; }).join('') || `<li class="muted small">${t('printListEmpty')}</li>`}</ul><div class="col mt"><button class="btn primary" onclick="printListRun()">${ic('printer')} ${t('printReports')} (${WQ.printList.length})</button><button class="btn" onclick="abbrevReport()">${ic('file')} ${t('abbreviatedReport')}</button></div><div class="help">${t('printListHelp')}</div></div></div></div>`; };
function wqAddPrint(key, silent) { if (!WQ.printList.includes(key)) WQ.printList.push(key); if (!silent) renderMain(); }
function wqAddAcc(acc) { const v = visitByAcc(acc); if (!v) return toast(t('visitNotFound'), 'error', acc); unitsOfVisit(v).forEach(u => wqAddPrint(u.key, true)); renderMain(); }
function wqBulk(status) { if (!WQ.rows.length) return; let n = 0; WQ.rows.forEach(u => { u.results.filter(r => r.value !== '' && stIdx(r.status) < stIdx(status)).forEach(r => { r.status = status; r.statusLog.push({ status, time: nowISO(), user: userName() }); n++; }); }); audit('Bulk ' + status, `${WQ.rows.length} reports`, `${n} results`); renderMain(); toast(`${t('st_' + status)} · ${n} ${t('results')}`, n ? 'ok' : 'warn', t('bulkWarn')); }
function printListRun() { if (!WQ.printList.length) return toast(t('printListEmpty'), 'warn'); const printable = WQ.printList.map(k => unitByKey(k)).filter(({ u }) => u.results.length && u.results.every(r => stIdx(r.status) >= 3 || DB.parameters.printUnverified)); const skipped = WQ.printList.length - printable.length; if (!printable.length) return toast(t('printRefused'), 'error', t('onlyVerifiedPrint')); WQ.printListNo++; printable.forEach(({ v, u }) => { v.printList = WQ.printListNo; u.results.forEach(r => { r.printed = true; if (r.status === 'Verified') r.status = 'Printed'; r.statusLog.push({ status: 'Printed', time: nowISO(), user: userName() }); }); }); audit('Print list', '#' + WQ.printListNo, `${printable.length} reports`); const first = printable[0]; WQ.printList = []; renderMain(); toast(`${t('printList')} #${WQ.printListNo} · ${printable.length} ${t('reports')}`, 'ok', skipped ? `${skipped} ${t('skippedNotVerified')}` : ''); reportModal(first.v, [first.u], false); }
function abbrevReport() { const units = (WQ.printList.length ? WQ.printList.map(k => unitByKey(k).u) : WQ.rows); if (!units.length) return toast(t('noResults'), 'warn'); modal({ title: t('abbreviatedReport'), size: 'lg', body: `<div class="paper">${paperHead(t('abbreviatedReport'))}<div class="small">${t('fileCopyOnly')} · ${fmtDT(NOW())} · ${WQ.printListNo > 704 ? t('printList') + ' #' + WQ.printListNo : ''}</div>${units.map(u => { const p = patientOf(u.visit); return `<div style="border:1px solid #cfd6e2;padding:8px;margin:8px 0"><div class="row"><b>${esc(p.name)}</b> · ${u.visit.acc} · ${fmtDT(u.visit.date)} · ${u.visit.locType} · ${p.no}</div><div class="small muted">${esc(L(grp(u.group)))}</div><table><tbody>${u.results.map(r => `<tr><td>${esc(L(testById(r.test), 'report'))}</td><td style="width:120px">${esc(r.value)}</td><td>[${esc(rangeText(testById(r.test), p))}]</td></tr>`).join('')}</tbody></table></div>`; }).join('')}</div>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button><button class="btn primary" onclick="toast(t('sentToPrinter'),'ok')">${ic('printer')} ${t('print')}</button>` }); }
App.screens.printReports = () => { WQ.f.boxes = { verified: true, notPrinted: true }; WQ.f.received = true; return App.screens.workQueue({}); };
App.screens.qc = () => pageHead(t('qualityControl'), `${t('laboratory')} / ${t('qualityControl')}`) + `<div class="info">${t('qcPlaceholder')}</div>` + card({ title: t('qcToday'), flush: true, body: grid({ cols: [{ k: 'analyzer', l: 'analyzer' }, { k: 'test', l: 'test' }, { k: 'level', l: 'level' }, { k: 'value', l: 'value' }, { k: 'target', l: 'target' }, { k: 'sd', l: 'sdIndex' }, { k: 'rule', l: 'westgard' }, { k: 'status', l: 'status', f: r => sb(r.status) }], rows: [{ id: 1, analyzer: 'XN-550', test: 'HGB', level: 'L1', value: 8.1, target: 8.0, sd: '+0.5', rule: '—', status: 'Normal' }, { id: 2, analyzer: 'XN-550', test: 'HGB', level: 'L2', value: 13.2, target: 13.0, sd: '+0.8', rule: '—', status: 'Normal' }, { id: 3, analyzer: 'Cobas c311', test: 'GLU', level: 'L1', value: 102, target: 95, sd: '+2.3', rule: '1-2s', status: 'High' }, { id: 4, analyzer: 'Cobas c311', test: 'CREA', level: 'L2', value: 3.9, target: 4.0, sd: '-0.4', rule: '—', status: 'Normal' }], nofoot: true }) });
